#!/usr/bin/env python3
"""
Local Reasoning Engine — matches opportunities against 500+ distilled decisions.
Zero LLM calls. Returns verdict + evidence + confidence in < 100ms.
"""

import json
import sqlite3
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

ROOT = Path(__file__).resolve().parents[4]  # master_investments/
DB_PATH = ROOT / ".claude" / "data" / "knowledge-distillation" / "decision-vectors.db"
KILL_SIGNALS_PATH = ROOT / ".claude" / "data" / "knowledge-distillation" / "kill-signals.json"


@dataclass
class Verdict:
    decision: str  # KILL, SIDE_HUSTLE, MOUNTAIN_CANDIDATE, NEEDS_LLM
    score: float
    confidence: float
    evidence: list = field(default_factory=list)
    kill_reasons: list = field(default_factory=list)
    similar_decisions: list = field(default_factory=list)

    def to_dict(self):
        return {
            "verdict": self.decision,
            "score": round(self.score, 3),
            "confidence": round(self.confidence, 3),
            "evidence": self.evidence,
            "kill_reasons": self.kill_reasons,
            "similar_decisions": self.similar_decisions[:5],
        }


class KnowledgeDB:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or DB_PATH
        if not self.db_path.exists():
            raise FileNotFoundError(f"Decision vectors DB not found: {self.db_path}")
        self.conn = sqlite3.connect(str(self.db_path))
        self.conn.row_factory = sqlite3.Row

    def get_all_vectors(self):
        rows = self.conn.execute("SELECT * FROM decision_vectors").fetchall()
        results = []
        for row in rows:
            r = dict(row)
            r["features"] = json.loads(r["features_json"])
            r["kill_signals"] = json.loads(r["kill_signals"] or "[]")
            r["success_signals"] = json.loads(r["success_signals"] or "[]")
            r["lesson_tags"] = json.loads(r["lesson_tags"] or "[]")
            results.append(r)
        return results

    def get_failures(self):
        rows = self.conn.execute(
            "SELECT * FROM decision_vectors WHERE outcome = 'failure'"
        ).fetchall()
        return [dict(r) for r in rows]

    def count(self):
        return self.conn.execute("SELECT COUNT(*) FROM decision_vectors").fetchone()[0]

    def close(self):
        self.conn.close()


FEATURE_WEIGHTS = {
    "industry": 1.0,
    "business_model": 1.5,
    "entry_capital": 1.0,
    "moat_type": 2.0,
    "leverage_type": 2.0,
    "founder_type": 0.8,
    "market_timing": 1.2,
    "contrarian_level": 0.5,
    "time_horizon": 0.8,
}


class SimilarityMatcher:
    def __init__(self, vectors: list):
        self.vectors = vectors

    def compute_similarity(self, query_features: dict, stored_features: dict) -> float:
        total_weight = 0.0
        weighted_score = 0.0

        for feature, weight in FEATURE_WEIGHTS.items():
            q_val = query_features.get(feature)
            s_val = stored_features.get(feature)
            if q_val is None or s_val is None:
                continue

            total_weight += weight

            if isinstance(q_val, list) and isinstance(s_val, list):
                # Jaccard for array features (moat_type, leverage_type)
                q_set = set(q_val)
                s_set = set(s_val)
                if q_set or s_set:
                    jaccard = len(q_set & s_set) / len(q_set | s_set)
                    weighted_score += weight * jaccard
            elif isinstance(q_val, (int, float)) and isinstance(s_val, (int, float)):
                # Normalized distance for numeric (contrarian_level)
                max_val = 10.0
                dist = abs(q_val - s_val) / max_val
                weighted_score += weight * (1.0 - dist)
            else:
                # Exact match for enum features
                if q_val == s_val:
                    weighted_score += weight

        return weighted_score / total_weight if total_weight > 0 else 0.0

    def find_similar(self, query_features: dict, top_k: int = 10) -> list:
        scored = []
        for vec in self.vectors:
            sim = self.compute_similarity(query_features, vec["features"])
            scored.append((sim, vec))
        scored.sort(key=lambda x: x[0], reverse=True)
        return scored[:top_k]


class KillScanner:
    def __init__(self, kill_signals_path: Optional[Path] = None):
        self.path = kill_signals_path or KILL_SIGNALS_PATH
        self.rules = []
        if self.path.exists():
            self.rules = json.loads(self.path.read_text(encoding="utf-8"))

    def scan(self, features: dict) -> list:
        triggered = []
        for rule in self.rules:
            conditions = rule.get("conditions", {})
            match_count = 0
            total = len(conditions)
            if total == 0:
                continue

            for feat, values in conditions.items():
                feat_val = features.get(feat)
                if isinstance(values, list):
                    if isinstance(feat_val, list):
                        if set(values) & set(feat_val):
                            match_count += 1
                    elif feat_val in values:
                        match_count += 1
                elif feat_val == values:
                    match_count += 1

            match_ratio = match_count / total
            if match_ratio >= rule.get("threshold", 0.8):
                triggered.append({
                    "rule": rule.get("name", "unknown"),
                    "match_ratio": round(match_ratio, 2),
                    "description": rule.get("description", ""),
                    "seen_in": rule.get("seen_in_count", 0),
                })
        return triggered


class ScoreAggregator:
    OUTCOME_SCORES = {
        "success": 1.0,
        "mixed": 0.5,
        "failure": 0.0,
        "pending": 0.5,
    }

    def aggregate(self, similar_decisions: list) -> tuple:
        """Returns (score, confidence) from top-K similar decisions."""
        if not similar_decisions:
            return 0.5, 0.0

        top5 = similar_decisions[:5]
        weighted_sum = 0.0
        weight_sum = 0.0

        for similarity, vec in top5:
            outcome = vec.get("outcome", "pending")
            outcome_score = self.OUTCOME_SCORES.get(outcome, 0.5)
            weighted_sum += outcome_score * similarity
            weight_sum += similarity

        score = weighted_sum / weight_sum if weight_sum > 0 else 0.5

        avg_sim = sum(s for s, _ in top5) / len(top5)
        coverage = 1.0 if avg_sim > 0.7 else 0.5
        confidence = min(avg_sim * coverage * 1.2, 1.0)

        return score, confidence


class VerdictGenerator:
    def generate(self, score: float, confidence: float, kill_reasons: list) -> str:
        if kill_reasons and any(r["match_ratio"] >= 0.9 for r in kill_reasons):
            return "KILL"
        if confidence < 0.6:
            return "NEEDS_LLM"
        if score < 0.3:
            return "KILL"
        if score <= 0.6:
            return "SIDE_HUSTLE"
        return "MOUNTAIN_CANDIDATE"


class LocalReasoningEngine:
    def __init__(self, db_path: Optional[Path] = None, kill_signals_path: Optional[Path] = None):
        self.db = KnowledgeDB(db_path)
        self.vectors = self.db.get_all_vectors()
        self.matcher = SimilarityMatcher(self.vectors)
        self.kill_scanner = KillScanner(kill_signals_path)
        self.aggregator = ScoreAggregator()
        self.verdict_gen = VerdictGenerator()

    def evaluate(self, features: dict) -> Verdict:
        kill_reasons = self.kill_scanner.scan(features)

        similar = self.matcher.find_similar(features, top_k=10)
        score, confidence = self.aggregator.aggregate(similar)

        decision = self.verdict_gen.generate(score, confidence, kill_reasons)

        evidence = []
        for sim, vec in similar[:5]:
            evidence.append({
                "id": vec["id"],
                "similarity": round(sim, 3),
                "outcome": vec["outcome"],
                "summary": vec.get("narrative_summary", ""),
            })

        similar_ids = [vec["id"] for _, vec in similar[:5]]

        return Verdict(
            decision=decision,
            score=score,
            confidence=confidence,
            evidence=evidence,
            kill_reasons=kill_reasons,
            similar_decisions=similar_ids,
        )

    def stats(self) -> dict:
        return {
            "total_vectors": len(self.vectors),
            "kill_rules": len(self.kill_scanner.rules),
            "outcomes": {
                o: sum(1 for v in self.vectors if v["outcome"] == o)
                for o in ["success", "failure", "mixed", "pending"]
            },
        }

    def close(self):
        self.db.close()


def main():
    import argparse
    parser = argparse.ArgumentParser(description="Local Reasoning Engine CLI")
    parser.add_argument("--features", type=str, help="JSON features string")
    parser.add_argument("--stats", action="store_true", help="Show DB stats")
    args = parser.parse_args()

    try:
        engine = LocalReasoningEngine()
    except FileNotFoundError as e:
        sys.exit(str(e))

    if args.stats:
        print(json.dumps(engine.stats(), indent=2))
        engine.close()
        return

    if args.features:
        features = json.loads(args.features)
        verdict = engine.evaluate(features)
        print(json.dumps(verdict.to_dict(), indent=2))
    else:
        print(f"Engine loaded: {engine.stats()['total_vectors']} vectors, "
              f"{engine.stats()['kill_rules']} kill rules")
        print("Usage: --features '{...}' or --stats")

    engine.close()


