/**
 * Auto-distillation hook — fires after every /stage0 run.
 * Extracts decision vectors from the latest verdict JSON into the local knowledge DB.
 * Fail-open: errors are logged but never block the session.
 */
const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

const ROOT = process.env.CLAUDE_PROJECT_DIR || path.resolve(__dirname, '../..');
const SCRIPT = path.join(ROOT, '.claude', 'scripts', 'knowledge-distillation', 'auto-distill-case.py');
const CASES_DIR = path.join(ROOT, '.claude', 'skills', 'business', 'transaction-layer', 'nui-hunter', 'kb', 'cases');

try {
  // Only run if the latest case file was modified in the last 10 minutes (likely from this session)
  if (!fs.existsSync(CASES_DIR)) process.exit(0);

  const cases = fs.readdirSync(CASES_DIR)
    .filter(f => f.startsWith('stage0-') && f.endsWith('.json'))
    .map(f => ({ name: f, mtime: fs.statSync(path.join(CASES_DIR, f)).mtimeMs }))
    .sort((a, b) => b.mtime - a.mtime);

  if (cases.length === 0) process.exit(0);

  const latest = cases[0];
  const ageMinutes = (Date.now() - latest.mtime) / 60000;
  if (ageMinutes > 10) process.exit(0); // Not from this session

  const casePath = path.join(CASES_DIR, latest.name);
  const result = execSync(`python "${SCRIPT}" --case "${casePath}"`, {
    timeout: 10000,
    encoding: 'utf-8',
    cwd: ROOT,
  });

  if (result.includes('Total vectors')) {
    const match = result.match(/Total vectors in DB: (\d+)/);
    if (match) {
      process.stdout.write(`[auto-distill] +1 vector → DB now has ${match[1]} decisions\n`);
    }
  }
} catch (e) {
  // Fail-open: never block session end
  process.stderr.write(`[auto-distill] non-blocking error: ${e.message}\n`);
}

